-- полное мультимножественное равенство сырья и исходных audit-полей на закреплённой границе.
WITH s AS (SELECT topic,kafka_partition,kafka_offset,batch_id,received_at,event_json FROM {{source:oil_stg__event_log}}), t AS (SELECT topic,kafka_partition,kafka_offset,batch_id,received_at,event_json FROM {{target:oil_stg__event_log}}), d AS ((SELECT * FROM s EXCEPT ALL SELECT * FROM t) UNION ALL (SELECT * FROM t EXCEPT ALL SELECT * FROM s)) SELECT count(*) AS n FROM d;
